def lookup_customer(cursor, customer):
    query = f"SELECT email FROM customers WHERE customer_name = '{customer}'"
    return cursor.execute(query).fetchone()

def change_address(cursor, address, account_id):
    query = "UPDATE accounts SET postal_address = '" + address + "' WHERE account_id = ?"
    cursor.execute(query, (account_id,))

def remove_session(cursor, token):
    query = "DELETE FROM sessions WHERE session_token = '%s'" % token
    cursor.execute(query)

def add_note(cursor, note):
    query = "INSERT INTO notes (body) VALUES ('{}')".format(note)
    cursor.execute(query)

def search_products(cursor, prefix):
    query = f"SELECT sku FROM products WHERE title LIKE '{prefix}%'"
    return cursor.execute(query).fetchall()

def list_teams(cursor, names):
    quoted = ",".join("'" + name + "'" for name in names)
    query = "SELECT team_id FROM teams WHERE team_name IN (" + quoted + ")"
    return cursor.execute(query).fetchall()

